package com.estradaplay.comunista;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import java.io.*;import java.text.*;import java.util.*;import java.util.concurrent.*;
public final class OfflineCenterActivity extends ComponentActivity{private final int BG=Color.rgb(9,5,7),TEXT=Color.rgb(246,238,224),MUTED=Color.rgb(174,151,146),RED=Color.rgb(190,18,38),GREEN=Color.rgb(69,212,131);private LinearLayout page;private final ExecutorService io=Executors.newSingleThreadExecutor();@Override protected void onCreate(Bundle b){super.onCreate(b);load();}@Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}private void load(){ScrollView sv=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(18),dp(18),dp(18),dp(30));page.setBackgroundColor(BG);sv.addView(page);setContentView(UnifiedAppShell.wrap(this,"central",sv));page.addView(t("CENTRAL OFFLINE 2.0",27,TEXT,true));page.addView(t("Auditando alertas e mapa sem bloquear a interface…",13,MUTED,false));io.execute(()->{RoadPackStore store=new RoadPackStore(getApplicationContext());OfflineRoadStore roads=new OfflineRoadStore(getApplicationContext());long bytes=size(new File(getFilesDir(),"road_safety_packs"))+size(new File(getFilesDir(),"offline_road_packs"));runOnUiThread(()->render(store,roads,bytes));});}private void render(RoadPackStore s,OfflineRoadStore roads,long bytes){page.removeAllViews();page.addView(t("CENTRAL OFFLINE 2.0",27,TEXT,true));page.addView(t(DriveSettings.offlineTestMode(this)?"MODO TESTE OFFLINE · ATIVO":"Pronto para testar a proteção sem desligar a internet do aparelho.",12,DriveSettings.offlineTestMode(this)?GREEN:MUTED,true));for(String uf:new String[]{"RJ","MG","ES"}){int n=s.stateHazardCount(uf);long at=s.stateFetchedAt(uf);String date=at>0?new SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.getDefault()).format(new Date(at)):"não baixado";page.addView(t(uf+"  "+(n>0?"✓":"…")+"   "+n+" pontos\nÚltima base: "+date,16,n>0?GREEN:TEXT,true));}page.addView(t("Alertas locais: "+s.hazardCount()+" · mapa: "+roads.packCount()+" pacote(s)\nEspaço local: "+human(bytes),13,MUTED,false));Button test=new Button(this);test.setText(DriveSettings.offlineTestMode(this)?"ENCERRAR TESTE OFFLINE":"ATIVAR TESTE OFFLINE REAL");test.setTextColor(TEXT);test.setBackgroundColor(DriveSettings.offlineTestMode(this)?Color.rgb(55,85,65):RED);page.addView(test,new LinearLayout.LayoutParams(-1,dp(58)));test.setOnClickListener(v->{boolean on=!DriveSettings.offlineTestMode(this);DriveSettings.toggle(this,"offline_test_mode",on);Toast.makeText(this,on?"Internet bloqueada internamente para mapa/cobertura. Use a estrada normalmente.":"Modo online liberado novamente.",Toast.LENGTH_LONG).show();load();});Button check=new Button(this);check.setText("ATUALIZAR RJ + MG + ES");page.addView(check,new LinearLayout.LayoutParams(-1,dp(54)));check.setOnClickListener(v->{if(DriveSettings.offlineTestMode(this)){Toast.makeText(this,"Encerre o teste offline para atualizar.",Toast.LENGTH_LONG).show();return;}Intent i=new Intent(this,RoadSafetyService.class).setAction(RoadSafetyService.ACTION_PREFETCH_CORE);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);Toast.makeText(this,"Atualização iniciada.",Toast.LENGTH_LONG).show();});Button reload=new Button(this);reload.setText("RELER BASE LOCAL");reload.setOnClickListener(v->load());page.addView(reload,new LinearLayout.LayoutParams(-1,dp(50)));}private long size(File f){if(f==null||!f.exists())return 0;if(f.isFile())return f.length();long n=0;File[]a=f.listFiles();if(a!=null)for(File x:a)n+=size(x);return n;}private String human(long b){if(b<1024*1024)return(b/1024)+" KB";return String.format(Locale.getDefault(),"%.1f MB",b/1048576.0);}private TextView t(String v,float s,int c,boolean b){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}}
